  for (let i = 1; i < ITERACIONES_HASH; i++) hash = sha256(hash + salt);
  return hash;
}

function hexAleatorio(bytes) {
  try {
    return require('crypto').randomBytes(bytes).toString('hex');
  } catch (e) {
    let s = '';
    for (let i = 0; i < bytes * 2; i++) s += Math.floor(Math.random() * 16).toString(16);
    return s;
  }
}

// Comparación en tiempo constante para no filtrar información por tiempos.
function igualesSeguro(a, b) {
  if (typeof a !== 'string' || typeof b !== 'string' || a.length !== b.length) return false;
  let r = 0;
  for (let i = 0; i < a.length; i++) r |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return r === 0;
}
// --- Validación de sesión (lee EP02 Sesiones y EP01 Usuarios) -------------
// Una sesión no es válida si no existe, está cerrada, expiró o su usuario está INACTIVO.
function resolverSesion(token) {
  const t = norm(token);
  if (!t) return { ok: false, status: 401, error: 'Inicia sesión para continuar.' };
  const sesion = filas('Leer Sesiones').find((s) => s.session_token === t);
  if (!sesion) return { ok: false, status: 401, error: 'Tu sesión no es válida. Inicia sesión de nuevo.' };
  if (sesion.estado !== 'ACTIVA') return { ok: false, status: 401, error: 'Tu sesión fue cerrada. Inicia sesión de nuevo.' };
  if (new Date(sesion.expira_en).getTime() <= Date.now()) {
    return { ok: false, status: 401, error: 'Tu sesión expiró. Inicia sesión de nuevo.' };
  }
  const usuario = filas('Leer Usuarios').find((u) => u.usuario_id === sesion.usuario_id);
  if (!usuario || usuario.estado !== 'ACTIVO') {
    return { ok: false, status: 403, error: 'Esta cuenta está inactiva.' };
  }
  return { ok: true, sesion, usuario };
}
